import { unstable_cache } from 'next/cache';
import fs from 'fs/promises';
import path from 'path';

// Interface for Post
export interface Post {
  id: string;
  title: string;
  content: string;
  createdAt: string;
}

const DB_PATH = path.join(process.cwd(), 'posts.json');

// Helper to ensure DB file exists
async function ensureDb() {
  try {
    await fs.access(DB_PATH);
  } catch {
    await fs.writeFile(DB_PATH, JSON.stringify([]));
  }
}

// Internal function to fetch posts from "DB"
async function fetchPostsFromDb(): Promise<Post[]> {
  await ensureDb();
  const data = await fs.readFile(DB_PATH, 'utf-8');
  return JSON.parse(data);
}

// Cached version of getPosts using cache tags
export const getPosts = unstable_cache(
  async () => {
    return fetchPostsFromDb();
  },
  ['posts-cache-key'], // Key parts
  { tags: ['posts'] } // Cache tags
);

// Function to add a post (no caching needed here, it writes)
export async function addPostToDb(post: Post) {
  await ensureDb();
  const posts = await fetchPostsFromDb();
  posts.push(post);
  await fs.writeFile(DB_PATH, JSON.stringify(posts, null, 2));
}

