'use server';

import { revalidateTag } from 'next/cache';
import { addPostToDb } from './data';
import { v4 as uuidv4 } from 'uuid'; // Need uuid, but wait, I can just use random string if uuid is not installed.
// Or just Date.now().toString() for simplicity since I can't install packages easily without checking package.json first.
// Let's check if uuid is in package.json. It's not. I'll use crypto.randomUUID() which is built-in to Node.

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title || !content) {
    throw new Error('Title and content are required');
  }

  const newPost = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date().toISOString(),
  };

  await addPostToDb(newPost);

  // Invalidate the cache tag 'posts' so the next fetch gets fresh data
  revalidateTag('posts');
}

